UPDATE articulos a SET contenido=(SELECT string_agg(coalesce(v.texto,substring(a.contenido from v.inicio for v.largo)),'' ORDER BY v.orden) FROM (VALUES (0, 1, 38, NULL::text),(1,0,0,E'<thead><tr><th scope="col">Condición de aceptación del sistema o componente mecánico</th><th scope="col">Cumple</th><th scope="col">No cumple</th><th scope="col">N/A*</th></tr></thead>'),(2, 39, 15, NULL::text),(3, 175, 22, NULL::text),(4,0,0,E'<td colspan="3">'),(5, 201, 1539, NULL::text),(6,0,0,E'b) Los anillos de seguridad de piezas múltiples deben estar correctamente emparejados, sin perder su forma circular o estar doblados, chuecos, agrietados, flojos y/o botados, deben tener 3 mm (0.120") de holgura entre sus extremos.'),(7, 1976, 433, NULL::text),(8,0,0,E'b) En caso de que las ruedas presenten desviación lateral, esta debe ser igual o menor a 6 mm (1/4").'),(9, 2515, 508, NULL::text),(10,0,0,E'a) Los rines de disco deben instalarse en vehículos en los que los componentes instalados existentes estén diseñados para aceptar este tipo de rin. Los agujeros de birlo de los rines de disco deben estar sin abocardarse o dañarse de manera que impidan una instalación adecuada. Los birlos piloto de asientos esféricos de los rines de disco deben estar libres de daños que impidan la instalación adecuada de las tuercas. Las ruedas con mazas piloto deben estar exentas de tener cojinetes desgastados a fin de evitar una desviación radial mayor a 3 mm (1/8"). Las caras de montaje de las mazas de los rines de disco deben encontrarse libres de deformaciones y distorsiones de más de 0.50 mm (0.020").</td><td></td><td></td><td></td></tr><tr><td>b) Las superficies pintadas de los rines de disco deben tener una capa de pintura igual o menor de 0.089 mm (0.003"). Las mazas o tambores de rueda pintados deben instalarse en un vehículo con una superficie pintada y curada por 72 horas como mínimo.'),(11, 4031, 1282, NULL::text)) v(orden,inicio,largo,texto)) WHERE a.id='31117eaf-f0ec-510b-ac68-17ab694044e4' AND md5(a.contenido)='e349b296d8f7b7a1d25808c4610bcf06' RETURNING a.id,md5(a.contenido) hash;